using System.Data;using Backend.BDFolder;using Backend.Exceptions;using Backend.Helpers;using Backend.Models;using Backend.Policies;using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Logging;using Polly;namespace Backend.Services;public class PermisoService{    private readonly IDbContextFactory<TransportesRojasDbContext> _factory;    private readonly ILogger<PermisoService> _logger;    private readonly ResiliencePipeline _pipeline;    public PermisoService(        IDbContextFactory<TransportesRojasDbContext> factory,        ILogger<PermisoService> logger)    {        _factory = factory;        _logger = logger;        _pipeline = PollyPolicies.CrearPipelineSerializacion(logger);    }    public async Task<List<PermisoResponse>> GetPermisosAsync(int skip = 0, int take = 100)    {        await using var ctx = await _factory.CreateDbContextAsync();        return await ctx.Permisos            .AsNoTracking()            .OrderBy(p => p.Id)            .Skip(skip)            .Take(take)            .Select(p => new PermisoResponse(p.Id, p.Codigo, p.Nombre, p.Descripcion, p.Modulo))            .ToListAsync();    }    public async Task<PermisoResponse?> GetPermisoByIdAsync(long id)    {        await using var ctx = await _factory.CreateDbContextAsync();        var permiso = await ctx.Permisos            .AsNoTracking()            .FirstOrDefaultAsync(p => p.Id == id);        return permiso is null            ? null            : new PermisoResponse(permiso.Id, permiso.Codigo, permiso.Nombre, permiso.Descripcion, permiso.Modulo);    }    public async Task<PermisoResponse> CreatePermisoAsync(CrearPermisoModel model)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var existeCodigo = await ctx.Permisos                    .AnyAsync(p => p.Codigo == model.Codigo, ct);                if (existeCodigo)                    throw new InvalidOperationException(                        $"Ya existe un permiso con el código '{model.Codigo}'.");                var nuevo = new Permiso                {                    Codigo = model.Codigo,                    Nombre = model.Nombre,                    Descripcion = model.Descripcion,                    Modulo = model.Modulo,                    CreatedAt = DateTimeOffset.UtcNow                };                ctx.Permisos.Add(nuevo);                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Permiso creado. Id={Id}, Codigo='{Codigo}'",                    nuevo.Id, nuevo.Codigo);                return new PermisoResponse(nuevo.Id, nuevo.Codigo, nuevo.Nombre, nuevo.Descripcion, nuevo.Modulo);            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException("Conflicto de serialización al crear permiso.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    public async Task<bool> UpdatePermisoAsync(long id, ActualizarPermisoModel model)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var permiso = await ctx.Permisos.FindAsync(new object[] { id }, ct);                if (permiso is null) return false;                var existeCodigo = await ctx.Permisos                    .AnyAsync(p => p.Codigo == model.Codigo && p.Id != id, ct);                if (existeCodigo)                    throw new InvalidOperationException(                        $"Ya existe otro permiso con el código '{model.Codigo}'.");                permiso.Codigo = model.Codigo;                permiso.Nombre = model.Nombre;                permiso.Descripcion = model.Descripcion;                permiso.Modulo = model.Modulo;                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Permiso actualizado. Id={Id}", id);                return true;            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException("Conflicto de serialización al actualizar permiso.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    public async Task<bool> DeletePermisoAsync(long id)    {        return await _pipeline.ExecuteAsync(async ct =>        {            await using var ctx = await _factory.CreateDbContextAsync(ct);            await using var tx = await ctx.Database                .BeginTransactionAsync(IsolationLevel.Serializable, ct);            try            {                var permiso = await ctx.Permisos.FindAsync(new object[] { id }, ct);                if (permiso is null) return false;                var estaEnUso = await ctx.RolPermisos                    .AnyAsync(rp => rp.PermisoId == id, ct);                if (estaEnUso)                    throw new InvalidOperationException(                        "No se puede eliminar el permiso porque está asignado a uno o más roles.");                ctx.Permisos.Remove(permiso);                await ctx.SaveChangesAsync(ct);                await tx.CommitAsync(ct);                _logger.LogInformation("Permiso eliminado. Id={Id}", id);                return true;            }            catch (Exception ex) when (PostgresErrorHelper.IsSerializationFailure(ex))            {                await RollbackSafeAsync(tx);                throw new RetryableException("Conflicto de serialización al eliminar permiso.", ex);            }            catch (InvalidOperationException)            {                await RollbackSafeAsync(tx);                throw;            }            catch (Exception)            {                await RollbackSafeAsync(tx);                throw;            }        }, CancellationToken.None);    }    private async Task RollbackSafeAsync(        Microsoft.EntityFrameworkCore.Storage.IDbContextTransaction tx)    {        try { await tx.RollbackAsync(); }        catch (Exception rollbackEx)        {            _logger.LogWarning(rollbackEx, "Error durante rollback (puede ser esperado).");        }    }}